import { z } from "zod";

import generated from "./generated/config.json";

// The slice of config/ the Worker needs, generated by `jobhunt build-shared`
// and validated here so a bad build fails at startup, not mid-conversation.
// The enums mirror the CHECK constraints in migrations/0001_initial.sql.

export const Level = z.enum(["student_intern", "fresh_grad", "junior", "mid", "senior"]);
export const Location = z.enum(["bangladesh", "remote"]);
export const JobType = z.enum(["full_time", "internship", "part_time", "contract"]);
export const Delivery = z.enum(["instant", "digest"]);
const ClockTime = z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/);
export const QuietHours = z.strictObject({ start: ClockTime, end: ClockTime });

export type Level = z.infer<typeof Level>;
export type Location = z.infer<typeof Location>;
export type JobType = z.infer<typeof JobType>;
export type Delivery = z.infer<typeof Delivery>;
export type QuietHours = z.infer<typeof QuietHours>;

const CallbackCode = z.string().regex(/^[a-z]{1,4}$/);

const SharedConfig = z.strictObject({
  domains: z.array(z.strictObject({ slug: z.string(), name: z.string() })),
  tracks: z.array(
    z.strictObject({
      id: z.string(),
      label: z.string(),
      description: z.string(),
      primary_domains: z.array(z.string()),
      adjacent_domains: z.array(z.string()),
      include_titles: z.array(z.string()),
    }),
  ),
  skills: z.array(
    z.strictObject({
      id: z.string(),
      name: z.string(),
      aliases: z.array(z.string()),
      category: z.string(),
    }),
  ),
  preferred_cities: z.array(z.strictObject({ id: z.string(), name: z.string() })),
  callbacks: z.strictObject({
    why: CallbackCode,
    applied: CallbackCode,
    save: CallbackCode,
    hide: CallbackCode,
    thumbs_up: CallbackCode,
    thumbs_down: CallbackCode,
    reason: CallbackCode,
  }),
  bot: z.strictObject({
    updates_per_minute: z.number().int().positive(),
    max_pause_days: z.number().int().positive(),
    cv_max_bytes: z.number().int().positive(),
    list_limit: z.number().int().positive(),
    max_skills: z.number().int().positive(),
    max_skill_length: z.number().int().positive(),
    experience_levels: z.array(Level).min(1),
    locations: z.array(Location).min(1),
    job_types: z.array(JobType).min(1),
    min_score_options: z.array(z.number().min(0).max(10)).min(1),
    quiet_hours_options: z.array(QuietHours),
    feedback_reasons: z.array(z.string()).min(1),
    defaults: z.strictObject({
      min_score: z.number(),
      delivery_mode: Delivery,
      max_per_cycle: z.number().int().positive(),
      include_adjacent: z.boolean(),
    }),
  }),
  github: z.strictObject({
    api_base_url: z.url({ protocol: /^https$/ }),
    repository: z.string().regex(/^[\w.-]+\/[\w.-]+$/),
  }),
  timezone: z.string(),
  max_age_days: z.number().int().positive(),
  notifications: z.strictObject({ max_attempts: z.number().int().positive() }),
});

export type SharedConfig = z.infer<typeof SharedConfig>;

export const CONFIG: SharedConfig = SharedConfig.parse(generated);
